"""Export the flat, joined 林 mark. Pillow only; never changes launcher components.

--check compares deterministic generated bytes with all checked-in bitmap assets.
"""
from pathlib import Path
import argparse, hashlib
from io import BytesIO
from PIL import Image, ImageDraw
ROOT=Path(__file__).resolve().parents[1]
MAIN=ROOT/'apps/android/app/src/main'
RES=MAIN/'res'
INK='#0B4A3D'
BACKGROUND='#8CE6CC'
# Two 木 share a single crossbar and a root, making one continuous 林 silhouette.
STROKES=[[(43,29),(43,95)],[(84,29),(84,95)],[(23,49),(104,49)],
    [(43,58),(24,81)],[(43,58),(61,80)],[(84,58),(66,80)],
    [(84,58),(103,81)],[(43,95),(63,91),(84,95)]]
def glyph(size,adaptive=False):
    n=size*4;im=Image.new('RGBA',(n,n));d=ImageDraw.Draw(im)
    def pos(x,y):
        return ((x*.56+18.16)*n/108,(y*.56+18.16)*n/108) if adaptive else (x*n/128,y*n/128)
    width=max(1,round(8*(.56*n/108 if adaptive else n/128)))
    radius=width/2
    for stroke in STROKES:
        coords=[pos(x,y) for x,y in stroke]
        d.line(coords,fill=INK,width=width,joint='curve')
        for x,y in (coords[0],coords[-1]):
            d.ellipse((x-radius,y-radius,x+radius,y+radius),fill=INK)
    return im.resize((size,size),Image.Resampling.LANCZOS)
def background(size):
    return Image.new('RGBA',(size,size),BACKGROUND)

def icon(size,rounded=False,store=False):
    im=background(size);im.alpha_composite(glyph(size))
    if not store:
        mask=Image.new('L',(size*4,size*4));d=ImageDraw.Draw(mask)
        if rounded:d.ellipse((0,0,size*4-1,size*4-1),fill=255)
        else:d.rounded_rectangle((0,0,size*4-1,size*4-1),radius=size*.22*4,fill=255)
        im.putalpha(mask.resize((size,size),Image.Resampling.LANCZOS))
    return im
def main():
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--preview',type=Path)
    p.add_argument('--preview-only',action='store_true');args=p.parse_args()
    if args.preview_only:
        if not args.preview: p.error('--preview-only requires --preview')
        icon(512).save(args.preview)
        return
    outputs={RES/'drawable-nodpi/ic_launcher_portrait.png':glyph(432,True),RES/'drawable-nodpi/ic_brand_logo.png':icon(512),MAIN/'artwork/store-icon-512.png':icon(512,store=True)}
    for density,size in {'mdpi':48,'hdpi':72,'xhdpi':96,'xxhdpi':144,'xxxhdpi':192}.items():
        for rounded in (False,True):outputs[RES/f'mipmap-{density}'/('ic_launcher_round.png' if rounded else 'ic_launcher.png')]=icon(size,rounded)
    for path,im in outputs.items():
        buf=BytesIO();im.save(buf,format='PNG');data=buf.getvalue()
        if args.check:assert path.read_bytes()==data,f'Stale asset: {path}'
        else:
            path.parent.mkdir(parents=True,exist_ok=True)
            path.write_bytes(data)
        print(str(path.relative_to(ROOT)),hashlib.sha256(data).hexdigest()[:16])
    if args.preview:icon(512).save(args.preview)
    points=[((x*.56+18.16)-54,(y*.56+18.16)-54) for p in STROKES for x,y in p]
    assert max((x*x+y*y)**.5 for x,y in points)<33
    print('13 bitmap assets consistent; adaptive geometry inside 33dp safe radius; components unchanged.')
if __name__=='__main__':main()
